/**
 * HyperMillSafetyHooks — CAM Safety Validations from hyperMILL Best Practices
 *
 * Safety hooks derived from hyperMILL Manual Parts 1-4. These validate
 * CAM parameters against documented constraints and best practices.
 *
 * All hooks use mode: "warning" (never blocking from document-learned knowledge).
 *
 * Source: document:hypermill-manual-en-{1,2,3,4}
 * Generated by /pdf-learn forge-triple pipeline
 */

// ============================================================================
// HOOK: Clearance Plane Safety
// ============================================================================

/**
 * Validates that clearance plane is positioned safely above the workpiece.
 *
 * From Manual 1: "The clearance plane is always situated above the workpiece
 * boundaries in the Z direction." and "Traversing movements on the clearance
 * plane are not checked with regard to collisions. Therefore this plane must
 * be placed at a sufficient distance above the surface of the workpiece."
  * @param params - configuration options
  * @returns { valid: boolean; warnings: string[] }
 */
export function validateClearancePlane(params: {
  clearancePlaneZ: number;
  workpieceTopZ: number;
  stockTopZ: number;
  fixtureTopZ?: number;
}): { valid: boolean; warnings: string[] } {
  const warnings: string[] = [];
  const { clearancePlaneZ, workpieceTopZ, stockTopZ, fixtureTopZ } = params;

  const maxZ = Math.max(workpieceTopZ, stockTopZ, fixtureTopZ ?? 0);

  if (clearancePlaneZ <= maxZ) {
    warnings.push(
      `CRITICAL: Clearance plane (Z=${clearancePlaneZ}) is at or below the highest ` +
      `obstruction (Z=${maxZ}). Rapid moves at clearance plane are NOT collision-checked. ` +
      `Set clearance plane above Z=${maxZ + 5} minimum. [hyperMILL Manual 1, p.759]`,
    );
  } else if (clearancePlaneZ - maxZ < 2) {
    warnings.push(
      `WARNING: Clearance plane (Z=${clearancePlaneZ}) is only ${(clearancePlaneZ - maxZ).toFixed(1)}mm ` +
      `above highest point (Z=${maxZ}). Recommend at least 5mm clearance for safety. ` +
      `[hyperMILL Manual 1]`,
    );
  }

  return { valid: warnings.length === 0, warnings };
}


// ============================================================================
// HOOK: Negative Allowance Constraint
// ============================================================================

/**
 * Validates negative allowance constraints to prevent nose-diving.
 *
 * From Manual 4: "Sum of (negative) stock allowance and tool corner radius
 * must not become negative." and "Surface gaps should not exceed:
 * 2 x (tool radius + negative allowance)."
  * @param params - configuration options
  * @returns { valid: boolean; warnings: string[] }
 */
export function validateNegativeAllowance(params: {
  allowanceMm: number;
  additionalAllowanceXY?: number;
  toolRadiusMm: number;
  toolCornerRadiusMm: number;
  machiningToleranceMm?: number;
}): { valid: boolean; warnings: string[] } {
  const warnings: string[] = [];
  const {
    allowanceMm,
    additionalAllowanceXY = 0,
    toolRadiusMm,
    toolCornerRadiusMm,
    machiningToleranceMm = 0.01,
  } = params;

  // Only check negative allowances
  if (allowanceMm >= 0 && additionalAllowanceXY >= 0) {
    return { valid: true, warnings: [] };
  }

  // Check 1: allowance + corner radius must not be negative
  if (allowanceMm < 0 && allowanceMm + toolCornerRadiusMm < 0) {
    warnings.push(
      `CRITICAL: Negative allowance (${allowanceMm}mm) + corner radius (${toolCornerRadiusMm}mm) = ` +
      `${(allowanceMm + toolCornerRadiusMm).toFixed(3)}mm (negative!). This will cause tool nose-diving. ` +
      `[hyperMILL Manual 4, p.757]`,
    );
  }

  // Check 2: end mills not allowed with negative XY allowance
  if (allowanceMm < 0 && toolCornerRadiusMm === 0) {
    warnings.push(
      `WARNING: Flat end mills (corner radius=0) are not allowed with negative allowance. ` +
      `Use a bullnose or ball end mill. [hyperMILL Manual 4, p.757]`,
    );
  }

  // Check 3: Additional allowance XY constraint
  if (additionalAllowanceXY < 0) {
    const totalNeg = Math.abs(allowanceMm + additionalAllowanceXY);
    const limit = toolRadiusMm - machiningToleranceMm;
    if (totalNeg >= limit) {
      warnings.push(
        `CRITICAL: |allowance(${allowanceMm}) + XY allowance(${additionalAllowanceXY})| = ${totalNeg.toFixed(3)}mm ` +
        `exceeds limit of ${limit.toFixed(3)}mm (tool radius - tolerance). ` +
        `[hyperMILL Manual 4, p.758]`,
      );
    }
  }

  // Check 4: Max surface gap warning
  if (allowanceMm < 0) {
    const maxGap = 2 * (toolRadiusMm + allowanceMm);
    if (maxGap > 0) {
      warnings.push(
        `INFO: With negative allowance ${allowanceMm}mm, surface gaps must not exceed ` +
        `${maxGap.toFixed(2)}mm to avoid nose-diving. [hyperMILL Manual 4, p.757]`,
      );
    }
  }

  return { valid: warnings.filter((w) => w.startsWith("CRITICAL")).length === 0, warnings };
}


// ============================================================================
// HOOK: Geometry Check Status
// ============================================================================

/**
 * Warns if automatic geometry check is disabled.
 *
 * From Manual 1: "This function should always be enabled (it is active by
 * default) in order to avoid faulty calculations."
  * @param params - configuration options
  * @returns { valid: boolean; warnings: string[] }
 */
export function validateGeometryCheckEnabled(params: {
  automaticGeometryCheck: boolean;
}): { valid: boolean; warnings: string[] } {
  if (!params.automaticGeometryCheck) {
    return {
      valid: false,
      warnings: [
        `WARNING: Automatic geometry check is DISABLED. This can cause faulty ` +
        `calculations when geometry is modified. Re-enable in Setup > Settings > ` +
        `Calculation > Automatic geometry check. [hyperMILL Manual 1, p.36]`,
      ],
    };
  }
  return { valid: true, warnings: [] };
}


// ============================================================================
// HOOK: Measurement System Consistency
// ============================================================================

/**
 * Warns about measurement system changes during CAM programming.
 *
 * From Manual 1: "Do not change the measurement system during CAM programming,
 * as definition values that have already been created will not be converted.
 * Copying jobs between hyperMILL documents with different measurement systems
 * is not allowed."
  * @param params - configuration options
  * @returns { valid: boolean; warnings: string[] }
 */
export function validateMeasurementSystem(params: {
  currentSystem: "metric" | "inch";
  projectSystem: "metric" | "inch";
  hasExistingJobs: boolean;
}): { valid: boolean; warnings: string[] } {
  if (params.currentSystem !== params.projectSystem && params.hasExistingJobs) {
    return {
      valid: false,
      warnings: [
        `CRITICAL: Measurement system mismatch! Project uses ${params.projectSystem} but ` +
        `current setting is ${params.currentSystem}. Existing job values will NOT be ` +
        `converted. Do not change measurement system with existing jobs. ` +
        `[hyperMILL Manual 1, p.35]`,
      ],
    };
  }
  return { valid: true, warnings: [] };
}


// ============================================================================
// HOOK: Turning Tool Validation
// ============================================================================

/**
 * Validates turning tool constraints for High Performance Mode.
 *
 * From Manual 2: "Only turning tools with a round insert are permitted
 * in High Performance Mode."
  * @param params - configuration options
  * @returns { valid: boolean; warnings: string[] }
 */
export function validateTurningHPM(params: {
  highPerformanceMode: boolean;
  insertType: "round" | "diamond" | "square" | "trigon" | "other";
}): { valid: boolean; warnings: string[] } {
  if (params.highPerformanceMode && params.insertType !== "round") {
    return {
      valid: false,
      warnings: [
        `WARNING: High Performance Mode requires round inserts only. Current insert ` +
        `type '${params.insertType}' is not permitted in HPM. Switch to a round insert ` +
        `or disable HPM. [hyperMILL Manual 2, p.303]`,
      ],
    };
  }
  return { valid: true, warnings: [] };
}


// ============================================================================
// HOOK: Rest Material Tool Diameter
// ============================================================================

/**
 * Warns about tool diameter changes affecting rest material recognition.
 *
 * From Manual 3: "If the tool diameter is changed in the milling cycle
 * generating the rest material, the corresponding rest material cycle must
 * also be changed. Otherwise, there is a risk that the tool could plunge
 * into the material."
  * @param params - configuration options
  * @returns { valid: boolean; warnings: string[] }
 */
export function validateRestMaterialToolChange(params: {
  previousToolDiameterMm: number;
  currentToolDiameterMm: number;
  isRestMaterialCycle: boolean;
  restMaterialToolDiameterMm?: number;
}): { valid: boolean; warnings: string[] } {
  const warnings: string[] = [];

  if (
    params.isRestMaterialCycle &&
    params.restMaterialToolDiameterMm !== undefined &&
    params.previousToolDiameterMm !== params.restMaterialToolDiameterMm
  ) {
    warnings.push(
      `WARNING: The reference cycle tool diameter (${params.previousToolDiameterMm}mm) ` +
      `differs from the rest material cycle's reference (${params.restMaterialToolDiameterMm}mm). ` +
      `Update the rest material cycle to match. Risk of tool plunging into material. ` +
      `[hyperMILL Manual 3, p.638]`,
    );
  }

  return { valid: warnings.length === 0, warnings };
}
